/* The UI atlas: one 8-bit alpha texture holding pre-rendered Roboto glyphs at a few sizes
 * plus icon shapes. Generated by tools/make_atlas.py into atlas_data.c. */
#ifndef WIITUBE_ATLAS_H
#define WIITUBE_ATLAS_H

typedef struct {
    short x, y, w, h;      /* region in the atlas */
    short xoff, yoff;      /* offset of the region from the pen position on the baseline */
    short advance;
} atlas_glyph;

typedef struct {
    short size, ascent, descent, line_height;
    atlas_glyph glyphs[96]; /* ASCII 32..126, then 127 = bullet */
} atlas_font;

typedef struct {
    short x, y, w, h;
} atlas_rect;

enum { FONT_META, FONT_SMALL, FONT_TITLE, FONT_BODY, FONT_BIG, FONT_HUGE, FONT_COUNT };

enum {
    ICON_WHITE,       /* solid block, for plain fills */
    ICON_CIRCLE,      /* filled disc */
    ICON_CORNER_INV,  /* square minus a quarter disc (top-left corner mask) */
    ICON_PLAY,
    ICON_PAUSE,
    ICON_SEARCH,
    ICON_VOLUME,
    ICON_BACK,
    ICON_CURSOR_FILL,
    ICON_CURSOR_EDGE,
    ICON_RING,        /* circle outline */
    ICON_HOME,
    ICON_SHORTS,
    ICON_GEAR,
    ICON_CHEVRON,     /* pointing down (mirror vertically for up) */
    ICON_CHEVRON_RIGHT, /* mirror horizontally for left */
    ICON_CHECK,
    ICON_COUNT
};

extern const int atlas_w, atlas_h;
extern const unsigned char atlas_i8[]; /* atlas_w * atlas_h alpha values, row-major */
extern const atlas_font atlas_fonts[FONT_COUNT];
extern const atlas_rect atlas_icons[ICON_COUNT];

#endif
